import { useEffect, useState } from "react";

function AdminStock() {
    const [itemsList, setItemsList] = useState([]);

    useEffect(() => {
        fetch('http://localhost:3001/')
            .then(response => response.json())
            .then(data => {
                setItemsList(data);
            })
            .catch(error => {
                console.error('Erreur lors de la récupération des articles :', error);
            });
    }, [])

    return (
        <div>
            <table>
                <thead>
                    <tr>
                        <th>Nom</th>
                        <th>Description</th>
                        <th>Prix</th>
                        <th>Quantité</th>
                        <th>Image</th>
                        <th>Action</th>
                    </tr>
                </thead>
                <tbody>
                    {itemsList.map((article) => (
                        <tr>
                            <td>{article.name}</td>
                            <td>{article.name}</td>
                            <td>{article.name}</td>
                            <td>{article.name}</td>
                            <td>{article.name}</td>
                            <td>{article.name}</td>
                        </tr>
                    ))
                    }
                </tbody>
            </table>
        </div>
    );
}
export default AdminStock;
